      padding: 40px 20px;
    }

    .page {
      width: min(920px, 100%);
      background: var(--surface);
      border: 1px solid rgba(255, 255, 255, 0.65);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
      overflow: hidden;
