      font-size: 1.05rem;
      line-height: 1.7;
    }

    .faq-list {
      padding: 28px;
      display: grid;
      gap: 18px;
    }

    .example {
      background: rgba(255, 255, 255, 0.92);
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      overflow: hidden;
      transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
    }

    .example:hover {
      transform: translateY(-2px);
      box-shadow: 0 16px 35px rgba(19, 34, 56, 0.08);
      border-color: rgba(91, 124, 255, 0.3);
    }

    .question {
      width: 100%;
      border: 0;
      background: transparent;
      color: inherit;
      padding: 24px 26px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      font: inherit;
      font-size: 1.08rem;
      font-weight: 700;
      text-align: left;
      cursor: pointer;
