    .question:focus-visible {
      outline: 3px solid rgba(91, 124, 255, 0.32);
      outline-offset: -3px;
    }

    .indicator {
      flex: 0 0 auto;
      width: 36px;
      height: 36px;
      border-radius: 50%;
      display: grid;
      place-items: center;
      background: var(--accent-soft);
