      transition: transform 180ms ease, background 180ms ease;
      font-size: 1.4rem;
      line-height: 1;
    }

    .example.is-open .indicator {
      transform: rotate(45deg);
      background: rgba(91, 124, 255, 0.18);
    }

    .details {
      display: grid;
      grid-template-rows: 0fr;
      transition: grid-template-rows 220ms ease;
    }

    .example.is-open .details {
      grid-template-rows: 1fr;
    }

    .details-inner {
      overflow: hidden;
    }

    .answer {
      margin: 0;
      padding: 0 26px 24px;
      color: var(--muted);
      line-height: 1.7;
      font-size: 1rem;
